mapper.select:
SELECT DISTINCT bmat.id, bmat.reserve_id, bmat.reserve_name, bmat.room_id, bmat.room_name, bmat.service_type, bmat.service_status, bmr.meeting_type, bmr.retained_audio, bmr.start_time, bm.swept, bm.used, bmat.create_time FROM bbx_meeting_attendant_task bmat LEFT JOIN bbx_meeting_attendant_room bmar ON bmar.room_id = bmat.room_id LEFT JOIN bbx_meeting_reserve bmr ON bmr.id = bmat.reserve_id LEFT JOIN bbx_meeting_room bm ON bmat.room_id = bm.id
AND bmr.tenant_id =#{condition.tenantId}
AND bmat.service_type=#{condition.serviceType}
AND bmar.user_id = #{condition.userId}
AND bmat.service_valid = 1 AND bmar.status = 1 AND bmat.service_status != 3 AND bmr.draft = 0 AND bm.deleted = 1
order by bmat.create_time
${condition.orderByDirection}

SELECT DISTINCT bmat.id, bmat.reserve_id, bmat.reserve_name, bmat.room_id, bmat.room_name, bmat.service_type, bmat.service_status, bmr.start_time, bmr.end_time, bmat.create_time FROM bbx_meeting_attendant_task bmat LEFT JOIN bbx_meeting_attendant_room bmar ON bmar.room_id = bmat.room_id LEFT JOIN bbx_meeting_reserve bmr ON bmr.id = bmat.reserve_id LEFT JOIN bbx_meeting_room bm ON bmat.room_id = bm.id
AND bmat.tenant_id =#{condition.tenantId}
AND bmat.service_type=#{condition.serviceType}
AND bmat.handle_uid = #{condition.userId}
AND (#{condition.endTime} >= bmr.end_time and #{condition.startTime} <= bmr.start_time)
AND bmat.room_name like concat('%',#{condition.roomName},'%')
AND bmat.reserve_name like concat('%',#{condition.reserveName},'%')
AND bmat.service_status = 3 AND bmat.handle_uid is not null AND bmar.status = 1
order by bmat.create_time desc

SELECT DISTINCT bmat.id, bmat.reserve_id, bmat.room_id, bmat.service_type, bmat.service_status, bmat.service_valid FROM bbx_meeting_attendant_task bmat LEFT JOIN bbx_meeting_reserve bmr ON bmr.id = bmat.reserve_id
AND bmat.room_id =#{roomId}
AND bmr.draft = 0

SELECT DISTINCT bmat.reserve_id, bmr.real_participant_number, bmat.handle_uid FROM bbx_meeting_attendant_task bmat LEFT JOIN bbx_meeting_reserve bmr ON bmr.id = bmat.reserve_id
AND bmr.tenant_id =#{condition.tenantId}
AND (#{condition.endTime} >= bmr.end_time and #{condition.startTime} <= bmr.start_time)
AND bmat.handle_uid in
#{userId}
AND bmr.draft = 0 AND bmat.service_status = 3 AND bmat.handle_uid is not null

SELECT bmat.id, bmat.reserve_id, bmat.room_id, bmat.service_status, bmat.service_valid, bmat.service_type, bmat.handle_uid FROM bbx_meeting_attendant_task bmat LEFT JOIN bbx_meeting_reserve bmr ON bmr.id = bmat.reserve_id
AND bmr.tenant_id =#{condition.tenantId}
AND ((bmat.handle_time BETWEEN #{condition.startTime} AND #{condition.endTime}) or (bmat.create_time BETWEEN #{condition.startTime} AND #{condition.endTime}))
AND bmat.handle_uid in
#{userId}
AND bmr.draft = 0

WITH week_dates AS ( SELECT TRUNC(SYSDATE, 'IW') - 1 + (LEVEL - 1) AS day_date FROM DUAL CONNECT BY LEVEL <= 7 )
SELECT w.day_date AS date, COALESCE(COUNT(t.id), 0) AS count FROM week_dates w LEFT JOIN bbx_meeting_attendant_task t ON TRUNC(t.handle_time) = w.day_date
AND t.service_status =#{serviceStatus}
AND t.tenant_id =#{tenantId}
GROUP BY w.day_date ORDER BY w.day_date;
